INSERT INTO tour_reviews (tour_slug, language, author, author_location, rating, review_date, title, content, verified, experience_type) VALUES
('shark-cage-diving-gansbaai', 'es', 'Marcus Rodriguez', 'Sydney, Australia', 5, '2024-01-16', 'Experiencia de Adrenalina Definitiva - Cara a Cara con Tiburones Blancos', 'El buceo en jaula con tiburones en Gansbaai ofreció el encuentro con vida silvestre más intenso de mi vida, combinando adrenalina palpitante con increíble educación sobre conservación marina. Como alguien que busca activamente experiencias de aventura extrema en todo el mundo, este encuentro con tiburones blancos superó todas las expectativas en seguridad, profesionalismo y emoción pura. El viaje en barco de 2 horas desde el puerto de Gansbaai proporcionó tiempo de preparación perfecto, con biólogos marinos compartiendo información fascinante sobre el comportamiento del tiburón blanco, patrones de migración y el papel crucial que estos depredadores ápice juegan en el equilibrio del ecosistema marino. Aprender sobre los desafíos de conservación de tiburones y las amenazas que enfrentan las poblaciones de tiburones blancos agregó contexto significativo que transformó esto de simple búsqueda de emociones en auténtica educación sobre vida silvestre. El momento de entrar en la jaula - suspendido en las oscuras aguas del Atlántico mientras tiburones blancos de 4 metros se deslizaban a solo centímetros de distancia - creó la conexión más poderosa con la naturaleza que jamás haya experimentado. La gracia, poder e inteligencia de los tiburones se hizo evidente inmediatamente, disipando completamente los miedos creados por Hollywood y reemplazándolos con profundo respeto por estas magníficas criaturas.', true, 'Vida Silvestre Extrema'),

('cape-town-paragliding', 'es', 'Sofia Martinez', 'Barcelona, España', 5, '2024-01-25', 'Aventura Aérea Impresionante - Parapente Sobre Ciudad del Cabo con Vistas de Table Mountain', 'El parapente en Ciudad del Cabo ofreció la experiencia aérea más espectacular imaginable, combinando emociones de deportes extremos con belleza natural impresionante que crea recuerdos inolvidables y perspectivas únicas de una de las ciudades más hermosas del mundo. Como alguien que ha practicado parapente en los Alpes, Andes e Himalayas, puedo decir con confianza que Ciudad del Cabo ofrece belleza escénica incomparable e instrucción profesional que se ubica entre los destinos de parapente globales. La experiencia de vuelo en tándem con instructores certificados proporcionó una introducción perfecta al parapente mientras aseguraba completa confianza en la seguridad. El briefing integral previo al vuelo cubrió condiciones climáticas, seguridad del equipo y procedimientos de vuelo, mientras que la instrucción profesional durante el vuelo mejoró la comprensión de técnicas de parapente y protocolos de seguridad. El despegue desde Signal Hill creó emoción inmediata mientras la belleza de Ciudad del Cabo se reveló desde perspectivas aéreas imposibles de lograr de otra manera. Volar sobre la costa atlántica con Table Mountain, Robben Island y la Península del Cabo extendidos abajo creó experiencias visuales que la fotografía no puede capturar adecuadamente - la escala, colores y geografía dramática requieren experiencia personal para apreciar completamente.', true, 'Aventura Aérea'),

-- Add French translations
('delaire-graff-estate', 'fr', 'Charlotte Williams', 'Londres, Royaume-Uni', 5, '2024-02-08', 'Excellence Viticole de Luxe - Domaine de Classe Mondiale avec Cuisine Étoilée Michelin', 'Le Domaine Delaire Graff représente le summum des expériences viticoles de luxe sud-africaines, combinant une viticulture exceptionnelle avec une hospitalité de classe mondiale, des collections d''art contemporain et une cuisine standard Michelin qui rivalise avec les meilleures destinations viticoles mondiales. Ce domaine de montagne de Stellenbosch offre une sophistication et une élégance qui dépassent les attentes du tourisme viticole premium tout en présentant l''excellence viticole sud-africaine. L''expérience de dégustation de vins a démontré une complexité et un raffinement remarquables à travers les offres variétales qui mettent en valeur l''expression optimale du terroir de Stellenbosch. Le Cabernet Sauvignon phare du Domaine Delaire Graff a affiché une profondeur exceptionnelle avec un chêne parfaitement intégré, des profils de fruits complexes et des structures de tanins élégantes qui démontrent des techniques de vinification magistrales comparables aux premiers crus bordelais. Les offres de Chardonnay ont révélé des caractéristiques de climat frais remarquables avec une complexité minérale et une acidité équilibrée qui valide le potentiel sud-africain pour une production de vin blanc de classe mondiale.', true, 'Vin de Luxe'),

-- Add German translations
('cape-of-good-hope', 'de', 'Emma Richardson', 'Edinburgh, Schottland', 5, '2024-01-30', 'Historisches Kap-Halbinsel - Afrikas Dramatischer Südwestlicher Punkt mit Reichem Seefahrtserbe', 'Das Kap der Guten Hoffnung bot den historisch bedeutendsten und natürlich spektakulärsten Abschluss unseres Kap-Halbinsel-Abenteuers, kombinierte dramatische Küstenlandschaften mit faszinierender Seefahrtsgeschichte und der symbolischen Errungenschaft, einen von Afrikas legendärsten geografischen Wahrzeichen zu erreichen. Diese UNESCO-Welterbestätte bietet Naturschönheit von Weltklasse und umfassende Bildung über südafrikanische Geschichte und globale maritime Erkundung. Die historische Bedeutung kann nicht überschätzt werden - an diesem legendären Kap zu stehen, wo portugiesische Entdecker erstmals Afrika auf der Route zu den asiatischen Gewürzmärkten umrundeten, schafft tiefgreifende Verbindungen mit Jahrhunderten globaler Erkundung, Handelsentwicklung und kulturellem Austausch, die die Weltgeschichte geprägt haben. Das Lernen über Bartolomeu Dias'' Errungenschaft von 1488 und Vasco da Gamas nachfolgende Reisen lieferte Kontext, der einfache Besichtigungen in bedeutungsvolle historische Bildung verwandelt.', true, 'Historisches Wahrzeichen'),

-- Add Portuguese translations
('babylonstoren-wine-estate', 'pt', 'Isabella Torres', 'Madrid, Espanha', 5, '2024-02-20', 'Paraíso do Jardim - Propriedade Vinícola Histórica com Jardins Botânicos de Classe Mundial', 'A Propriedade Vinícola Babylonstoren representa a síntese perfeita da excelência vitícola, arte botânica e preservação histórica que cria experiências transcendentes além do turismo vinícola típico. Esta propriedade do Cabo Holandês combina mais de 300 anos de tradição vinícola com design de jardim contemporâneo e inovação culinária que rivaliza com as melhores experiências de destino do mundo, mostrando o patrimônio agrícola sul-africano. Os jardins botânicos superaram todas as expectativas com seções temáticas meticulosamente projetadas que demonstram práticas agrícolas históricas ao lado de técnicas contemporâneas de agricultura sustentável. As hortas formais, pomares de frutas do patrimônio e coleções de plantas indígenas criam experiências educacionais que aumentam a apreciação pela diversidade agrícola sul-africana e tradições agrícolas históricas. O design do jardim demonstra arquitetura paisagística magistral que equilibra beleza estética com funcionalidade agrícola prática, criando espaços que inspiram enquanto educam os visitantes sobre produção sustentável de alimentos e gestão de ecossistemas.', true, 'Vinho e Jardins');

-- Create summary stats view
CREATE OR REPLACE VIEW tour_reviews_summary AS
SELECT 
    tour_slug,
    language,
    COUNT(*) as total_reviews,
    ROUND(AVG(rating), 2) as average_rating,
    COUNT(DISTINCT author) as unique_reviewers,
    MIN(review_date) as earliest_review,
    MAX(review_date) as latest_review,
    COUNT(CASE WHEN verified = true THEN 1 END) as verified_reviews,
    STRING_AGG(DISTINCT experience_type, ', ') as experience_types
FROM tour_reviews 
GROUP BY tour_slug, language
ORDER BY tour_slug, language;